import { render } from '@solidjs/web';
import { createSignal } from 'solid-js';
import Avatar from './avatar';
import './styles.css';

function App() {
  const [name, setName] = createSignal('Ada Lovelace');

  return (
    <>
      <input
        value={name()}
        onInput={(event) => setName(event.currentTarget.value)}
      />
      <div>
        <Avatar name={name()} />
        <Avatar name={name()} size={96} />
      </div>
    </>
  );
}

render(() => <App />, document.getElementById('app'));

export default function Avatar({ name, size }) {
  const initials = name
    .split(' ')
    .map((word) => word[0])
    .join('');

  return (
    <div
      class="avatar"
      style={{ width: `${size}px`, height: `${size}px`, 'font-size': `${size / 2.5}px` }}
    >
      {initials}
    </div>
  );
}

.avatar {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin: 0.5rem;
  border-radius: 50%;
  background: #446b9e;
  color: white;
  font-family: sans-serif;
  font-weight: bold;
}

import { render } from '@solidjs/web';
import { createSignal } from 'solid-js';
import Avatar from './avatar';
import './styles.css';

function App() {
  const [name, setName] = createSignal('Ada Lovelace');

  return (
    <>
      <input
        value={name()}
        onInput={(event) => setName(event.currentTarget.value)}
      />
      <div>
        <Avatar name={name()} />
        <Avatar name={name()} size={96} />
      </div>
    </>
  );
}

render(() => <App />, document.getElementById('app'));

export default function Avatar(props) {
  const size = () => props.size ?? 48;
  const initials = () =>
    props.name
      .split(' ')
      .filter(Boolean)
      .map((word) => word[0])
      .join('');

  return (
    <div
      class="avatar"
      style={{
        width: `${size()}px`,
        height: `${size()}px`,
        'font-size': `${size() / 2.5}px`,
      }}
    >
      {initials()}
    </div>
  );
}

.avatar {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin: 0.5rem;
  border-radius: 50%;
  background: #446b9e;
  color: white;
  font-family: sans-serif;
  font-weight: bold;
}
